    if(/轨迹|历史/.test(label))return ['time','history'];
    if(/完成|执行状态/.test(label))return ['complete','check'];
    if(/分布|占比|构成/.test(label))return ['income','overview'];
    if(/余额|现金|净额/.test(label))return ['income','assets'];
    if(/收益|收入|金币|估值|收支/.test(label))return ['income','coins'];
    if(/角色|账号|队伍/.test(label))return ['primary','roles'];
    if(/任务|排程|计划|分配|批次/.test(label))return ['primary','plan'];
