    const actual=summaryView(state,ui.start,ui.end,scope(),'actual'),dates=[...new Set(M.incomeRecords(state).filter(r=>r.date>=ui.start&&r.date<=ui.end&&M.scopedRecord(state,r,scope())).map(r=>r.date))],baseline=dates.reduce((n,d)=>n+summaryView(state,d,d,scope(),'estimated').net,0);
