    accounts=goldSorted(accounts);const page=Math.min(ui.goldListPage,Math.max(0,Math.ceil(accounts.length/8)-1));
    const matchedRows=goldSorted(accounts.flatMap(a=>a.visibleRows)),flatSearch=!!query&&accounts.length>1,searchPage=Math.min(ui.goldListPage,Math.max(0,Math.ceil(matchedRows.length/8)-1));
