  function editableTeams(t){return t.raidTeams?.length?M.clone(t.raidTeams):Array.from({length:t.runs},(_,i)=>({name:'团队 '+(i+1),playerSeats:t.raidPlayerSeats==='auto'?8:t.raidPlayerSeats,tankMode:'auto'}));}
  function raidTeamSources(){return state.plans.filter(p=>p.id!==ui.replacingPlanId&&p.batches.length&&(p.routeTaskIds||[p.taskId]).every(id=>state.tasks.find(t=>t.id===id)?.partyRule==='raid10')).sort((a,b)=>(b.updatedAt||b.createdAt||b.date).localeCompare(a.updatedAt||a.createdAt||a.date));}
