  function guide(){modal('开始使用 / 计算与数据口径',`<ol class="help-list"><li><b>1. 建立账号和角色</b>账号决定登录互斥和点卡用量。一个账号可拥有多个角色；未知信息保留待补。</li><li><b>2. 配置任务，选择参与范围</b>明确收益按角色或全队结算，设置每周期目标与执行日。周常多个执行日只使用周期中的第一个安排日。</li><li><b>3. 在任务中心安排并执行</b>在「安排任务」生成建议并确认，进入「排程与执行」调整或记录实际批次；录入后默认同步「周期进度」。以已确认排程作为执行依据，模板执行日只是偏好，手工完成标记不生成收益。</li></ol><div class="divider"></div><ul class="help-list"><li><b>经济净收益</b>金币 × 人民币价格 ÷ 金币单位 × 出售率 − 手续费 − 在线分钟 × 点卡单价 − 其他成本。</li><li><b>现金净收益 / 现金 ROI</b>实际兑现人民币 − 实际支付现金。ROI 分母是本期纳入的现金支付，零分母显示不适用。</li><li><b>操作时间与在线时间</b>操作分钟按执行批次计算；在线分钟按实际在线账号逐一累计。不同账号同时在线不把现实操作时间相加。</li><li><b>筛选与历史</b>角色与分组按任务直接收益和批内共享份额核算，手工归属优先；资料不足的记录保留待补。现金流始终是全空间记录。</li><li><b>存储与来源</b>数据保存在当前浏览器，建议定期导出 JSON。没有自动访问游戏目录或实时读取；示例数据始终标记示例。</li></ul>`);}
  function download(name,blob){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
