    modal('分享战报',`<div class="report-context"><span>${range.start} — ${range.end}</span><span>${range.mode==='actual'?'历史实测':'确认排程预测'} / ${range.currency==='gold'?'金币':range.currency==='rmb'?'人民币估值':'金币与人民币估值'}</span><span>1080 × 1440 PNG</span></div><div class="report-workbench"><details class="report-config" ${matchMedia('(min-width: 768px)').matches?'open':''}><summary>战报设置 <span id="report-config-summary"></span></summary><div class="report-settings"><fieldset><legend>分享内容</legend><div class="report-kind-options">${kinds.map(([v,l])=>`<label><input type="checkbox" name="report-kind" value="${v}" ${v==='summary'||v==='gold'?'checked':''}><span>${l}</span></label>`).join('')}</div></fieldset>${reportChoices('report-style','图片主题',[['cloud-blue','清爽浅色'],['deep-ocean','石墨深色'],['current','当前主题']],'cloud-blue')}${reportChoices('share-ranking','排行指标',[['hourly','净时薪'],['net','净收益'],['gross','毛收益']],'hourly')}${reportChoices('report-trend','趋势指标',[['net','经济净收益'],['minutes','操作时间']],'net')}<label class="share-privacy"><input type="checkbox" id="share-private" name="report-private" checked><span>匿名分享<small>隐藏账号、角色、分组与服务器</small></span></label><p class="share-hint" id="report-privacy-note"></p></div></details><section class="report-output" aria-label="战报预览"><div class="report-stage"><div class="report-preview-heading"><strong id="report-page-title"></strong><div class="report-page-navigation"><button type="button" id="report-previous" aria-label="预览上一张">上一张</button><span id="report-page-count" role="status"></span><button type="button" id="report-next" aria-label="预览下一张">下一张</button></div></div><canvas id="share-canvas" width="1080" height="1440" class="share-preview" role="img" aria-label="当前战报图片预览" aria-describedby="report-image-description"></canvas><details class="report-text-summary"><summary>查看文字摘要</summary><p id="report-image-description"></p></details><p id="report-status" class="share-hint" role="status" aria-live="polite"></p></div><nav class="report-pages" aria-label="战报图片列表"></nav></section></div>`,null);
    $('#dialog').classList.add('report-dialog');
