    const identities=[...identityMap].sort((a,b)=>b[0].length-a[0].length),scopeName=globalScopeLabel(selection,source);
    function options(){return {style:form.elements['report-style'].value,private:ui.privacy||$('#share-private').checked,ranking:form.elements['share-ranking'].value,trend:form.elements['report-trend'].value};}
