    if(ui.setupStep===0)content=`<div class="setup-options"><section class="card pad"><span class="pill">从零开始</span><h2 class="mt">建立自己的工作空间</h2><p class="panel-sub">常用任务已按正式服资料预置，先补充你的账号与角色。</p>${button('开始配置','setup-next','primary mt')}</section><section class="card pad"><span class="pill">已有备份</span><h2 class="mt">导入或加载已有数据</h2><p class="panel-sub">选择工作台 JSON、日期档案 JSON、角色 CSV 或 Excel，验证后再加载。</p><label class="field mt">选择 JSON / CSV / Excel<input id="import-file" type="file" accept=".json,.csv,.xlsx"></label><div id="import-preview"></div></section></div>${canExperience?`<section class="experience-start"><div><h2>先体验工作台</h2><p class="panel-sub">自动生成示例账号、角色、任务排程与收益记录，可随时退出并清空。</p></div>${button('直接体验','experience-start','primary')}</section>`:''}${dataStore.snapshots.length?archivePanel():''}`;
