    if(ui.setupStep===2)content=`<section class="card pad"><h2>配置任务和收益口径</h2><p class="panel-sub">默认任务已准备好，新角色自动加入。历史奖励标记待核对，随时修改收益、耗时和参与范围。</p><div class="flex wrap mt">${button('自定义任务','new-task','primary')}${button('编辑全局参数','edit-config')}</div><div class="summary-strip mt"><span>任务数量<b>${state.tasks.length}</b></span><span>最大并行<b>${state.config.concurrency} 开</b></span><span>币价<b>${money(state.config.goldPrice)} / ${num(state.config.goldUnit)} G</b></span></div>${setupTaskList()}</section>`;
    if(ui.setupStep===3)content=`<section class="card pad"><h2>工作空间已准备好</h2><p class="panel-sub">${state.accounts.length} 个账号 / ${state.roles.length} 个角色 / ${state.tasks.length} 个任务。每次修改会自动保存到当前浏览器，并按日期归档。</p>${!Store.hasData(state)?notice('当前仍为空白；进入后可随时配置，下次打开将再次提示配置引导。'):''}<p class="mt muted">导出 JSON 可以独立存放到你选择的文件夹，导入后在其他浏览器继续使用。</p><div class="flex wrap mt">${button('进入工作台','setup-finish','primary')}${button('导出当前数据','export')}</div></section>`;
    return pageHead('WORKSPACE SETUP','配置你的工作台',state.accounts.length?'已加载当前数据，可继续补充配置。':'尚无个人账号与角色。默认任务已预置，按步骤补充即可开始。',(experience?button('退出体验模式','experience-exit','danger'):button('跳过引导','setup-skip','ghost')))+`<ol class="setup-steps">${steps.map((name,i)=>`<li class="${i===ui.setupStep?'active':''}" ${i===ui.setupStep?'aria-current="step"':''}><button type="button" data-action="setup-step" data-step="${i}" aria-label="跳转到${name}"><span>${i+1}</span>${name}</button></li>`).join('')}</ol>`+`<div class="setup-content" tabindex="0" aria-label="当前步骤配置">${content}</div><div class="setup-footer flex between">${ui.setupStep?button('上一步','setup-back'): '<span></span>'}${ui.setupStep>0&&ui.setupStep<3?button('下一步','setup-next','primary'):''}</div>`;
