      const before=M.clone(state),previous=M.clone(dataStore),next=Store.restore(dataStore,id);next.active=M.upgradeState(next.active);Ops.ensureDefaults(next.active);M.capturePlanForecasts(next.active,next.snapshots);persist(next);state=M.clone(next.active);undoState=before;undoStore=previous;clearScope();ui.setup=!state.accounts.length&&!state.roles.length;ui.setupStep=0;render();toast('已加载 '+row.date+' 日期档案',true);
