  function startExperience(){
    if(experience||storageReadError||Store.hasData(state)||dataStore.snapshots.some(r=>Store.hasData(r.data)))throw new Error('请在空白工作空间进入体验模式');
    // Recheck persisted data so a stale empty tab cannot hide newly created personal data.
    const current=Store.read(localStorage).store;
    if(Store.hasData(current.active)||current.snapshots.some(r=>Store.hasData(r.data)))throw new Error('其他标签页已有数据，请刷新后继续');
    const sample=M.demo(M.dateKey());Ops.ensureDefaults(sample);M.freezeHistory(sample);M.capturePlanForecasts(sample,[]);
    Store.write(localStorage,Store.withState(Store.empty(),sample),DEMO_KEY);
    location.hash='';location.reload();
  }
  function exitExperience(){
    if(!experience)return;
    localStorage.removeItem(DEMO_KEY);
    // A reload also drops undo buffers, import previews and in-memory drafts.
    location.hash='';location.reload();
  }
